import{_ as e}from"./chunks/none.BOvQNh81.js";import{_ as a}from"./chunks/taa.BVy4jANc.js";import{_ as i}from"./chunks/msaa.Csk7w4Rk.js";import{_ as s}from"./chunks/fxaa.DCmrqC5I.js";import{_ as n}from"./chunks/toneMappingControl.VZWC7SL8.js";import{f as l,o,c as d,a2 as r}from"./chunks/framework.n5RLHRfo.js";const _=JSON.parse('{"title":"Antialiasing","description":"","frontmatter":{"title":"Antialiasing","order":10},"headers":[],"relativePath":"en/antialiasing/index.md","filePath":"en/antialiasing/index.md","lastUpdated":1792993711000}'),c={name:"en/antialiasing/index.md"};function g(h,t,p,m,u,A){return o(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="antialiasing" tabindex="-1">Antialiasing <a class="header-anchor" href="#antialiasing" aria-label="Permalink to &quot;Antialiasing&quot;">​</a></h1><p><strong>Antialiasing</strong> is a technique that removes jagged edges (aliasing) during 3D rendering to produce smooth outlines and surfaces. RedGPU provides temporal accumulation-based <strong><a href="./taa.html"><code>TAA</code></a></strong>, hardware multisampling-based <strong><a href="./msaa.html"><code>MSAA</code></a></strong>, and post-processing filter-based <strong><a href="./fxaa.html"><code>FXAA</code></a></strong>, all centrally controlled via <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/AntialiasingManager.html"><code>redGPUContext.antialiasingManager</code></a> (<a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/AntialiasingManager.html"><code>AntialiasingManager</code></a>).</p><hr><h2 id="_1-default-behavior-activation-rules" tabindex="-1">1. Default Behavior &amp; Activation Rules <a class="header-anchor" href="#_1-default-behavior-activation-rules" aria-label="Permalink to &quot;1. Default Behavior &amp; Activation Rules&quot;">​</a></h2><p>RedGPU&#39;s antialiasing system operates <strong>exclusively</strong>. Only one technique can be active at a time, and enabling a new technique automatically disables the previously active one.</p><h3 id="auto-selection-at-initialization" tabindex="-1">Auto-Selection at Initialization <a class="header-anchor" href="#auto-selection-at-initialization" aria-label="Permalink to &quot;Auto-Selection at Initialization&quot;">​</a></h3><p>Upon engine initialization, the optimal technique is automatically enabled based on the display pixel ratio (<code>window.devicePixelRatio</code>):</p><ul><li><strong>High-DPI Display</strong> (<code>devicePixelRatio &gt; 1.0</code>): <strong><a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/TAA.html"><code>TAA</code></a></strong> is enabled by default (<code>useTAA = true</code>).</li><li><strong>Standard Display</strong> (<code>devicePixelRatio &lt;= 1.0</code>): <strong><code>MSAA</code></strong> is enabled by default (<code>useMSAA = true</code>).</li></ul><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">antialiasingManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redGPUContext;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Switch antialiasing mode (automatically disables other modes)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">antialiasingManager.useTAA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><hr><h2 id="_2-comparison-of-techniques" tabindex="-1">2. Comparison of Techniques <a class="header-anchor" href="#_2-comparison-of-techniques" aria-label="Permalink to &quot;2. Comparison of Techniques&quot;">​</a></h2><p>Choose the appropriate technique based on your target rendering quality and performance budget.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Technique</th><th style="text-align:left;">Method</th><th style="text-align:left;">Quality &amp; Characteristics</th><th style="text-align:left;">Cost</th><th style="text-align:left;">Comparison Image</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>NONE</strong></td><td style="text-align:left;">Disabled</td><td style="text-align:left;">Raw rendering without antialiasing (visible jagged edges)</td><td style="text-align:left;">None</td><td style="text-align:left;"><img src="`+e+'" alt="None"></td></tr><tr><td style="text-align:left;"><strong><a href="./taa.html">TAA</a></strong></td><td style="text-align:left;">Temporal Accumulation</td><td style="text-align:left;">Resolves both geometry edges and internal shader/texture aliasing</td><td style="text-align:left;">Medium</td><td style="text-align:left;"><img src="'+a+'" alt="TAA"></td></tr><tr><td style="text-align:left;"><strong><a href="./msaa.html">MSAA</a></strong></td><td style="text-align:left;">Hardware Sampling</td><td style="text-align:left;">Smooths only geometry outlines (does not affect internal textures or alpha cutoff edges)</td><td style="text-align:left;">High</td><td style="text-align:left;"><img src="'+i+'" alt="MSAA"></td></tr><tr><td style="text-align:left;"><strong><a href="./fxaa.html">FXAA</a></strong></td><td style="text-align:left;">Post-processing</td><td style="text-align:left;">Fast screen-space edge smoothing (accompanied by slight image softness)</td><td style="text-align:left;">Very Low</td><td style="text-align:left;"><img src="'+s+'" alt="FXAA"></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Live Testing in Examples</strong>: You can switch and compare <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/TAA.html"><code>TAA</code></a>, <code>MSAA</code>, <a href="/RedGPU/manual/en/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/FXAA.html"><code>FXAA</code></a>, and <code>NONE</code> modes in real time on any running scene using the <strong><code>ANTIALIASING</code></strong> dropdown menu located in the UI of every RedGPU example.</p><p><img src="'+n+'" alt="Antialiasing Control"></p></div><hr><p><a href="./taa.html">Next Step: Learn TAA</a></p>',16)])])}const v=l(c,[["render",g]]);export{_ as __pageData,v as default};
